// C++: Mehr Details, dafür volle Kontrolle
#include <iostream>
#include <vector>

int main() {
    std::vector<std::string> namen = {"Anna", "Ben"};
    for (const auto& n : namen)
        std::cout << n << std::endl;
    return 0;
}
